use mtime_core::{EvidenceState,Provenance,QualityClass};
#[derive(Debug,Clone,Copy,PartialEq,Eq)]pub enum SightingStatus{Positive,Negative,Inconclusive,Invalidated}
#[derive(Debug,Clone,Copy,PartialEq,Eq)]pub enum VerificationStatus{Raw,Reviewed,Accepted,Rejected}
#[derive(Debug,Clone,PartialEq)]pub struct ObservationReport{pub id:String,pub site_id:String,pub organization:String,pub longitude_deg:f64,pub latitude_deg:f64,pub time_start_utc:String,pub time_end_utc:String,pub instrument:Option<String>,pub weather:Option<String>,pub horizon_condition:Option<String>,pub sighting:SightingStatus,pub verification:VerificationStatus,pub attachment_hashes:Vec<String>,pub evidence:EvidenceState,pub quality:QualityClass,pub provenance:Provenance}
impl ObservationReport{#[must_use]pub fn is_positive_accepted(&self)->bool{self.sighting==SightingStatus::Positive&&self.verification==VerificationStatus::Accepted}}
#[cfg(test)]mod tests{use super::*;#[test]fn raw_positive_is_not_accepted_testimony(){let r=ObservationReport{id:"1".into(),site_id:"A".into(),organization:"O".into(),longitude_deg:0.0,latitude_deg:0.0,time_start_utc:"x".into(),time_end_utc:"y".into(),instrument:None,weather:None,horizon_condition:None,sighting:SightingStatus::Positive,verification:VerificationStatus::Raw,attachment_hashes:vec![],evidence:EvidenceState::Observed,quality:QualityClass::Reference,provenance:Provenance::new("fixture")};assert!(!r.is_positive_accepted());}}
